self.KB_CONTENT["card:755399"]={"id":"card:755399","ty":"card","sourceId":"755399","title":"『批號資料建立作業』中的『異動別 (MF009)』為何？","ver":"iGP","topic":"銷貨","keywords":["銷貨","異動","入庫","批號"],"y":"other","answer":"* 不可空白。* 計有1.入庫、2.銷貨、3.領用、4.轉撥、5.調整五種。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
