self.KB_CONTENT["card:755117"]={"id":"card:755117","ty":"card","sourceId":"755117","title":"『合約訂單建立作業』中的『有效截止日期 (TW007)』為何？","ver":"iGP","topic":"客戶","keywords":["客戶","訂單","結案","複製"],"y":"other","answer":"* 不可空白。* 表示此合約訂單的有效截止日期。* 未結案合約訂單若已過有效截止日期，複製到客戶訂單建立作業時，仍可帶入但會SHOW警告訊息！","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
