self.KB_CONTENT["card:780313"]={"id":"card:780313","ty":"card","sourceId":"780313","title":"『進口費用建立作業』中的『原幣費用金額 (TJ012)』為何？","ver":"GP4以上","topic":"費用","keywords":["費用","單頭","稅額","原幣"],"y":"other","answer":"* 為子單頭原幣未稅金額累計。* 預設原幣費用總計=原幣稅額+原幣費用金額。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
