self.KB_CONTENT["card:780667"]={"id":"card:780667","ty":"card","sourceId":"780667","title":"『IPSR14 SHIPPING INSTRUCTION』中的『選擇列印單價別』為何？","ver":"GP4以上","topic":"採購單","keywords":["採購單","單價"],"y":"other","answer":"* 列印單價別其項目有1.採購單價(一)、2.採購單價(二)及3.採購單價(三)。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
