self.KB_CONTENT["card:782618"]={"id":"card:782618","ty":"card","sourceId":"782618","title":"『銀行資金預估狀況表』中的『選擇截止日期』為何？","ver":"GP4以上","topic":"狀況表","keywords":["狀況表","銀行","大於","等於"],"y":"other","answer":"* 可點選(icon)或按[F2]日期快手查詢，不可空白。* 所輸入之截止日期需大於或等於系統日期。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
