self.KB_CONTENT["card:780465"]={"id":"card:780465","ty":"card","sourceId":"780465","title":"『進口單據清除作業』中的『選擇單號』為何？","ver":"GP4以上","topic":"單號","keywords":["單號","進口","清除"],"y":"other","answer":"* 可點選(icon)或[F2]單據資料查詢。若輸入時為空白表全部皆納入。* 當輸入起迄單號後按才將資料寫入ListView中。例：若起迄單號都輸則寫入起始單號、截止單號；僅輸入起始單號則寫入≧起始單號；僅輸入截止單號則寫入≦截止單號。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
