self.KB_CONTENT["field:872155"]={"id":"field:872155","ty":"field","sourceId":"872155","title":"本期銷售淨額","ver":"iGP 1.0.8.以上","topic":"","keywords":[],"job":"產品成本分析表","code":"","answer":"『進耗存統計表』【本期銷售淨額】依據為實際銷貨成本，銷貨之單位成本為當月份的月加權平均單位成本，而產品成本分析表的單位成本僅包含當月份的製令成本，不含月初的數量金額，因此兩者成本不同。","file":"fields.jsonl"};
