self.KB_CONTENT["field:813338"]={"id":"field:813338","ty":"field","sourceId":"813338","title":"已領用量","ver":"GP4.0.10.0以上","topic":"","keywords":[],"job":"製令單建立作業","code":"","answer":"可以執行製令/託外管理系統->清單與明細表->『製令明細表』，用【選擇確認日期】作為條件，並勾選【是否列印材料明細】，即可呈現製令單單頭【已領套數】和單身的【已領用量】。","file":"fields.jsonl"};
